import {createHash} from 'node:crypto';
import {readFileSync} from 'node:fs';
import {zipSync,strToU8} from 'fflate';
import {components} from './plugin.mjs';

/** Only the fixed release download boundary is replaced with generated bytes.
 * Manifest/hash validation, installation, worker execution and all host domains
 * remain real. This is not evidence of a live GitHub release installation. */
export function generatedFinanceRelease() {
  const files=Object.fromEntries(['plugin.mjs','semantic-mock.mjs','fixtures.mjs','case-input.mjs'].map(name=>[name,[strToU8(readFileSync(new URL(name,import.meta.url),'utf8')),{mtime:new Date('2026-10-19T00:00:00Z')}]]));
  const archive=zipSync(files),repository='generated-benchmark/finance',tag='v1';
  const manifest={schemaVersion:1,id:'benchmark.finance',name:'Generated finance extension',version:'1',runtime:'worker',entry:'plugin.mjs',archive:{asset:'finance.zip',sha256:createHash('sha256').update(archive).digest('hex')},capabilities:['source','model'],configuration:[{id:'semanticFixture',label:'Generated semantic fixture only',type:'boolean'}],dependencies:[],access:['Explicitly granted synthetic finance source originals','Host-authorized semantic model requests'],components};
  const base=`https://github.com/${repository}/releases/download/${tag}/`;
  const transport=async url=>{
    if(url===`https://api.github.com/repos/${repository}/releases/tags/${tag}`)return {bytes:strToU8(JSON.stringify({tag_name:tag,draft:false,assets:[{name:'mote-plugin.json',browser_download_url:base+'mote-plugin.json'},{name:'finance.zip',browser_download_url:base+'finance.zip'}]}))};
    if(url===`https://api.github.com/repos/${repository}/commits/${tag}`)return {bytes:strToU8(JSON.stringify({sha:'1'.repeat(40)}))};
    if(url===base+'mote-plugin.json')return {bytes:strToU8(JSON.stringify(manifest))};
    if(url===base+'finance.zip')return {bytes:archive};
    throw Error('Unapproved release URL: '+url);
  };
  return {repository,tag,manifest,transport};
}
